#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000UL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char key[16], iv[12], tag[16], aad[32];
    memset(pt, 1, n);
    memset(key, 2, 16);
    memset(iv, 3, 12);
    memset(aad, 4, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_aes_128_gcm();

    /* warmup */
    int len = 0;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct + len, &len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("avg %.4f s  throughput %.1f MB/s\n", (t1-t0)/reps, n / ((t1-t0)/reps) / 1e6);

    /* reuse ctx without re-setting cipher? */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("reuse avg %.4f s  throughput %.1f MB/s\n", (t1-t0)/reps, n / ((t1-t0)/reps) / 1e6);

    /* in-place */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        memcpy(ct, pt, n);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, ct, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("inplace avg %.4f s  throughput %.1f MB/s\n", (t1-t0)/reps, n / ((t1-t0)/reps) / 1e6);

    EVP_CIPHER_CTX_free(ctx);
    free(pt); free(ct);
    return 0;
}
EOF
