{"command":"# multi-thread independent AES-GCM throughput
cat > mt_bench.c << 'EOF'
#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *pt, *ct;
    size_t n;
    int reps;
} Arg;

void *worker(void *p) {
    Arg *a = p;
    unsigned char key[16] = {1}, iv[12] = {2}, tag[16];
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len;
    for (int i = 0; i < a->reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, a->ct, &len, a->pt, (int)a->n);
        EVP_EncryptFinal_ex(ctx, a->ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    int threads_list[] = {1, 2, 3, 4, 6};
    size_t total = 60000UL * 1024;
    for (int ti = 0; ti < 5; ti++) {
        int T = threads_list[ti];
        size_t chunk = total / T;
        unsigned char *pt = malloc(total);
        unsigned char *ct = malloc(total);
        memset(pt, 3, total);
        pthread_t th[8];
        Arg args[8];
        int reps = 3;
        /* warmup */
        args[0] = (Arg){pt, ct, chunk, 1};
        worker(&args[0]);
        double t0 = now();
        for (int i = 0; i < T; i++) {
            args[i] = (Arg){pt + i*chunk, ct + i*chunk, chunk, reps};
            pthread_create(&th[i], NULL, worker, &args[i]);
        }
        for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        double t1 = now();
        double elapsed = (t1 - t0) / reps;
        printf("threads %d: %.4f s  %.1f MB/s\n", T, elapsed, total / elapsed / 1e6);
        free(pt); free(ct);
    }
    return 0;
}
EOF
cc -O3 -o mt_bench mt_bench.c -I/usr/local/include -L/usr/local/lib -lcrypto -lpthread && ./mt_bench"}

