/* GF(2^128) mul, NIST bit order (MSB is x^127). Standard GHASH multiplication. */
typedef unsigned __int128 u128;

static u128 load_be(const unsigned char b[16]) {
    u128 x = 0;
    for (int i = 0; i < 16; i++) x = (x << 8) | b[i];
    return x;
}
static void store_be(u128 x, unsigned char b[16]) {
    for (int i = 15; i >= 0; i--) { b[i] = (unsigned char)x; x >>= 8; }
}
static u128 gf_mul(u128 x, u128 y) {
    u128 z = 0;
    u128 v = x;
    /* R = 0xe1 << 120 */
    const u128 R = ((u128)0xe1) << 120;
    for (int i = 0; i < 128; i++) {
        if ((y >> (127 - i)) & 1) z ^= v;
        u128 lsb = v & 1;
        v >>= 1;
        if (lsb) v ^= R;
    }
    return z;
}
static u128 gf_pow(u128 h, size_t exp) {
