       which in NIST bit order is the least significant bit = 1, i.e. value 1. */
    u128 r = 1; /* identity: x^0 */
    u128 b = h;
    while (exp) {
        if (exp & 1) r = gf_mul(r, b);
        b = gf_mul(b, b);
        exp >>= 1;
    }
    return r;
