extern void gcm_ghash_clmul(uint64_t Xi[2], const uint64_t Htable[16][2], const uint8_t *inp, size_t len);
extern void gcm_gmult_clmul(uint64_t Xi[2], const uint64_t Htable[16][2]);
extern void gcm_init_avx(uint64_t Htable[16][2], const uint64_t *H);
extern void gcm_ghash_avx(uint64_t Xi[2], const uint64_t Htable[16][2], const uint8_t *inp, size_t len);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
static void hex(const char *l, const void *p, int n){printf("%-18s ", l); const unsigned char *b=p; for(int i=0;i<n;i++) printf("%02x", b[i]); printf("\n");}
static void bswap16(const unsigned char in[16], unsigned char out[16]){for(int i=0;i<16;i++) out[i]=in[15-i];}
static void bswap8(const unsigned char in[16], unsigned char out[16]){
    for(int i=0;i<8;i++){out[i]=in[7-i]; out[8+i]=in[15-i];}
}

int main(){
    unsigned char keyb[16]; for(int i=0;i<16;i++) keyb[i]=i+1;
    unsigned char iv[12]={0};
    unsigned char pt[32]; for(int i=0;i<32;i++) pt[i]=i+1;
    unsigned char ct[32], tag[16];
    EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new(); int len;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, iv);
    EVP_EncryptUpdate(ctx, ct, &len, pt, 32);
    EVP_EncryptFinal_ex(ctx, ct+len, &len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    /* E(J0), H */
    EVP_CIPHER_CTX *ecb=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ecb, EVP_aes_128_ecb(), NULL, keyb, NULL);
    EVP_CIPHER_CTX_set_padding(ecb, 0);
    unsigned char j0[16]={0}; j0[15]=1;
    unsigned char ej0[16], H[16], zero[16]={0}; int l2;
    EVP_EncryptUpdate(ecb, ej0, &l2, j0, 16);
    EVP_EncryptInit_ex(ecb, NULL, NULL, NULL, NULL);
    EVP_EncryptUpdate(ecb, H, &l2, zero, 16);
    unsigned char expect[16]; for(int i=0;i<16;i++) expect[i]=tag[i]^ej0[i];
    /* expect is GHASH(ct || lenblock). lenblock bitlen=256=0x100 */
    unsigned char lenb[16]={0}; lenb[15]=0x00; lenb[14]=0x01; /* 256 */
    unsigned char buf[48]; memcpy(buf, ct, 32); memcpy(buf+32, lenb, 16);
    hex("expect ghash", expect, 16);
    hex("H", H, 16);
    hex("ct", ct, 32);

    unsigned char variants[4][16];
    bswap16(H, variants[0]);
    bswap8(H, variants[1]);
    memcpy(variants[2], H, 16);
    /* reflected bits per byte */
    for(int i=0;i<16;i++){unsigned char a=H[i], r=0; for(int k=0;k<8;k++) r|=((a>>k)&1)<<(7-k); variants[3][i]=r;}

    const char *names[]={"bswap16","bswap8","raw","bitrev"};
    for (int v = 0; v < 4; v++) {
        uint64_t Htable[16][2];
        memset(Htable, 0, sizeof Htable);
        gcm_init_clmul(Htable, (uint64_t*)variants[v]);
        uint64_t Xi[2]={0,0};
        gcm_ghash_clmul(Xi, Htable, buf, 48);
        char lab[64];
        snprintf(lab, 64, "clmul %s", names[v]);
        hex(lab, Xi, 16);
        /* also try ghash of byte-swapped buf */
        unsigned char bufs[48];
        for (int i=0;i<48;i++) bufs[i]=buf[47-i];
        uint64_t Xi2[2]={0,0};
        gcm_ghash_clmul(Xi2, Htable, bufs, 48);
        snprintf(lab, 64, "clmul %s revbuf", names[v]);
        hex(lab, Xi2, 16);
    }

    /* Try avx init */
    printf("--- avx ---\n");
    for (int v = 0; v < 4; v++) {
        uint64_t Htable[32][2];
        memset(Htable, 0, sizeof Htable);
        gcm_init_avx(Htable, (uint64_t*)variants[v]);
        uint64_t Xi[2]={0,0};
        gcm_ghash_avx(Xi, Htable, buf, 48);
        char lab[64]; snprintf(lab,64,"avx %s", names[v]);
        hex(lab, Xi, 16);
    }
    return 0;
}
