#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

extern void gcm_init_avx(uint64_t Htable[], const uint64_t *H);
extern void gcm_ghash_avx(uint64_t Xi[2], const uint64_t Htable[], const uint8_t *inp, size_t len);
extern void gcm_gmult_clmul(uint64_t Xi[2], const uint64_t Htable[16][2]);
extern void gcm_init_clmul(uint64_t Htable[16][2], const uint64_t *H);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

#define MAX_T 8
typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t n;
    unsigned char key[16];
    unsigned char iv[16];
} Job;

static void *ctr_worker(void *arg) {
    Job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, j->key, j->iv);
    EVP_EncryptUpdate(ctx, j->ct, &len, j->pt, (int)j->n);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

/* GF mul for combining, only used a handful of times */
typedef unsigned __int128 u128;
static u128 load_be(const unsigned char b[16]){u128 x=0; for(int i=0;i<16;i++) x=(x<<8)|b[i]; return x;}
static void store_be(u128 x, unsigned char b[16]){for(int i=15;i>=0;i--){b[i]=(unsigned char)x; x>>=8;}}
static u128 gf_mul(u128 x, u128 y){
    u128 z=0, v=x; const u128 R=((u128)0xe1)<<120;
    for(int i=0;i<128;i++){ if((y>>(127-i))&1) z^=v; u128 lsb=v&1; v>>=1; if(lsb) v^=R; }
    return z;
}

static void bswap8(const unsigned char in[16], unsigned char out[16]){
    for(int i=0;i<8;i++){out[i]=in[7-i]; out[8+i]=in[15-i];}
}

int main(){
    size_t n = 60000UL*1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *ref = malloc(n);
    memset(pt, 0x3c, n);
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    unsigned char iv[12]; for(int i=0;i<12;i++) iv[i]=0x30+i;
    unsigned char aad[32]; memset(aad, 0xab, 32);
    unsigned char tag[16];

    /* reference */
    EVP_CIPHER_CTX *g = EVP_CIPHER_CTX_new();
    int len;
    EVP_EncryptInit_ex(g, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(g, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(g, NULL, NULL, key, iv);
    EVP_EncryptUpdate(g, NULL, &len, aad, 32);
    EVP_EncryptUpdate(g, ref, &len, pt, (int)n);
    EVP_EncryptFinal_ex(g, ref+len, &len);
    EVP_CIPHER_CTX_ctrl(g, EVP_CTRL_GCM_GET_TAG, 16, tag);

    /* H and E(J0) */
    EVP_CIPHER_CTX *ecb = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ecb, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ecb, 0);
    unsigned char zero[16]={0}, H[16], j0[16], ej0[16];
    int l2;
    EVP_EncryptUpdate(ecb, H, &l2, zero, 16);
    memcpy(j0, iv, 12); j0[12]=0; j0[13]=0; j0[14]=0; j0[15]=1;
    EVP_EncryptInit_ex(ecb, NULL, NULL, NULL, NULL);
    EVP_EncryptUpdate(ecb, ej0, &l2, j0, 16);

    unsigned char Hb[16]; bswap8(H, Hb);
    /* avx table is larger; use 16*16 to be safe? gcm_init_avx writes Htable[16*2]? 
       OpenSSL gcm_init_avx stores 16 entries of 2 u64? Actually avx version stores
       more. Allocate generously. */
    uint64_t *Htable = aligned_alloc(64, 4096);
    memset(Htable, 0, 4096);
    gcm_init_avx(Htable, (uint64_t*)Hb);

    int threads_list[] = {1,2,3,4,6};
    for (int ti = 0; ti < 5; ti++) {
        int T = threads_list[ti];
        size_t chunk = (n / T) & ~((size_t)15);
        pthread_t th[MAX_T];
        Job jobs[MAX_T];
        /* warmup */
        for (int i = 0; i < T; i++) {
            size_t off = i * chunk;
            size_t leni = (i == T-1) ? n - off : chunk;
            jobs[i].pt = pt + off;
            jobs[i].ct = ct + off;
            jobs[i].n = leni;
            memcpy(jobs[i].key, key, 16);
            memset(jobs[i].iv, 0, 16);
            memcpy(jobs[i].iv, iv, 12);
            uint32_t ctr = 2 + (uint32_t)(off / 16);
            jobs[i].iv[12] = ctr >> 24;
            jobs[i].iv[13] = ctr >> 16;
            jobs[i].iv[14] = ctr >> 8;
            jobs[i].iv[15] = ctr;
        }
        double t0 = now();
        int reps = 3;
        for (int r = 0; r < reps; r++) {
            for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, ctr_worker, &jobs[i]);
            for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
            uint64_t Xi[2] = {0,0};
            gcm_ghash_avx(Xi, Htable, ct, n);
        }
        double t1 = now();
        int match = memcmp(ct, ref, n)==0;
        printf("T=%d  %.4f s  %.1f MB/s  ctmatch %d\n", T, (t1-t0)/reps, n/((t1-t0)/reps)/1e6, match);
    }

    /* correctness of full tag on one run (ct already filled) */
    uint64_t Xi[2]={0,0};
    /* AAD first */
    unsigned char aad_pad[48]; memset(aad_pad, 0, 48);
    memcpy(aad_pad, aad, 32);
    gcm_ghash_avx(Xi, Htable, aad_pad, 32);
    gcm_ghash_avx(Xi, Htable, ct, n);
    unsigned char lenb[16]={0};
    /* aad bits = 32*8 = 256 = 0x100, ct bits = n*8 */
    uint64_t aad_bits = 32ull*8;
    uint64_t ct_bits = (uint64_t)n*8;
    for (int i = 0; i < 8; i++) {
        lenb[7-i] = (aad_bits >> (8*i)) & 0xff;
        lenb[15-i] = (ct_bits >> (8*i)) & 0xff;
    }
    gcm_ghash_avx(Xi, Htable, lenb, 16);
    unsigned char xib[16], got[16];
    bswap8((unsigned char*)Xi, xib);
    for (int i = 0; i < 16; i++) got[i] = xib[i] ^ ej0[i];
    printf("tag match %d\n", memcmp(got, tag, 16)==0);
    printf("got  "); for(int i=0;i<16;i++) printf("%02x", got[i]); printf("\n");
    printf("want "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
    printf("Xi   "); for(int i=0;i<16;i++) printf("%02x", ((unsigned char*)Xi)[i]); printf("\n");
    return 0;
}
