#include <openssl/evp.h>

extern void gcm_init_avx(uint64_t Htable[], const uint64_t *H);
extern void gcm_ghash_avx(uint64_t Xi[2], const uint64_t Htable[], const uint8_t *inp, size_t len);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
