    unsigned char *ct;
    size_t n;
    unsigned char key[16];
    unsigned char iv[16];
    pthread_mutex_t *mu;
    pthread_cond_t *cv;
    int *done;
    int idx;
} Job;

static void *ctr_worker(void *arg) {
    Job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
