   We precompute tables for H^{2^i}. */
#define MAXPOW 28
static uint64_t pow_table[MAXPOW][16][2];
static int pow_ready;

static void init_powers(const unsigned char Hb[16]) {
    /* pow_table[0] = table for H^1 */
    gcm_init_clmul(pow_table[0], (const uint64_t*)Hb);
    uint64_t cur[2];
    memcpy(cur, Hb, 16); /* cur = H */
    for (int i = 1; i < MAXPOW; i++) {
        /* cur = cur^2 */
        gcm_gmult_clmul(cur, pow_table[i-1]); /* cur = cur * H^{2^{i-1}} = (H^{2^{i-1}})^2 */
        gcm_init_clmul(pow_table[i], cur);
    }
    pow_ready = 1;
}

