static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
static void bswap8(const unsigned char *in, unsigned char *out){
    for(int i=0;i<8;i++){out[i]=in[7-i]; out[8+i]=in[15-i];}
}

#define MAXPOW 28
static uint64_t pow_table[MAXPOW][16][2];

/* Hb is the bswap8 form that gcm_init wants. Element form of H equals
   ghash(some block)/block, which we found equals raw ghash output, and
   gcm_init wants bswap8 of the AES(0) key, NOT the element. 
