static void init_table_from_elem(uint64_t table[16][2], const uint64_t elem[2]) {
    unsigned char e[16], b[16];
    memcpy(e, elem, 16);
    if (g_init_mode == 1) { bswap8(e, b); gcm_init_clmul(table, (uint64_t*)b); }
    else gcm_init_clmul(table, (uint64_t*)e);
