static void init_table_from_elem(uint64_t table[16][2], const unsigned char elem[16]) {
    unsigned char b[16];
    bswap8(elem, b);
    gcm_init_clmul(table, (uint64_t *)b);
}

static void ensure_powers(const unsigned char H[16]) {
